package webui

// stylesTasks is the task audit base; stylesTasksBatching is the mobile task-batching refinement (v33).
// Each const holds one contiguous slice of the stylesheet; the global order is
// reassembled in styles_desktop_app.go. Keep every const byte-identical to the
// corresponding line range of the original single-const layout.
const stylesTasks = `.task-filter-panel{margin-bottom:10px;border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.task-filter-panel>summary{min-height:50px;display:flex;align-items:center;justify-content:space-between;padding:9px 14px}.task-filter-panel>summary b{display:block;font-size:11px}.task-filter-panel>summary i{font-style:normal}.audit-query{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr)) auto auto;align-items:end;gap:7px;padding:12px 14px;border-top:1px solid var(--line);background:var(--surface-2)}.audit-query label{display:grid;gap:3px;color:var(--muted);font-size:9px;font-weight:700}.audit-query>a{min-height:42px;display:flex;align-items:center;color:var(--accent);font-size:9px}.audit-live{display:flex;align-items:center;gap:6px;margin-bottom:12px;padding:7px 10px;border-radius:7px;background:var(--green-soft);color:var(--green);font-size:9px}.audit-live i{width:6px;height:6px;border-radius:50%;background:var(--green)}.task-timeline{position:relative}.task-timeline:before{content:"";position:absolute;left:15px;top:9px;bottom:9px;width:1px;background:var(--line-2)}.task-event{position:relative;display:grid;grid-template-columns:32px minmax(0,1fr);gap:10px;margin-bottom:9px}.timeline-marker{position:relative;z-index:2;display:flex;justify-content:center}.timeline-marker>i{width:11px;height:11px;margin-top:18px;border:3px solid var(--canvas);border-radius:50%;background:var(--muted);box-shadow:0 0 0 1px var(--line-2)}.timeline-marker>i.ok{background:var(--green)}.timeline-marker>i.warn{background:var(--amber)}.timeline-marker>i.bad{background:var(--red)}.task-event-card{border:1px solid var(--line);border-radius:9px;background:var(--surface);box-shadow:var(--shadow);overflow:hidden}.task-event.focused .task-event-card{outline:2px solid var(--accent);background:var(--accent-soft)}.task-event-card>header{display:flex;align-items:flex-start;justify-content:space-between;padding:12px 14px;border-bottom:1px solid var(--line)}.event-action{display:grid;grid-template-columns:auto auto;align-items:center;gap:4px 8px}.event-action>small,.event-action>form{grid-column:2}.event-action strong{font-size:12px}.event-action small,.task-event time small{color:var(--muted);font-size:8px}.event-action form button{border:0;background:transparent;color:var(--accent);padding:0;font-size:9px}.task-event time{text-align:right}.task-event time b{display:block;font-size:9px}.task-event-body{display:grid;grid-template-columns:minmax(360px,.9fr) 1fr;gap:14px;padding:12px 14px}.event-target{display:flex;align-items:center;gap:10px}.event-target>span b,.event-target>span small{display:block}.event-target>span b{font-size:8px}.event-target>span small{color:var(--muted);font-size:8px}.task-lifecycle{padding-left:10px;border-left:1px solid var(--line)}.event-result{min-width:0;color:var(--muted);font-size:9px}.event-result summary{color:var(--accent);font-weight:700}.task-result-block{margin-top:8px}.task-result-block>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;color:var(--ink-2)}.task-result-block>header button{border:0;background:transparent;color:var(--accent);font-size:8px;font-weight:700}.event-result pre{max-height:220px;overflow:auto;margin:0;padding:9px;border:1px solid var(--line);border-radius:6px;background:var(--surface-2);font-size:9px;white-space:pre-wrap}.event-result pre.task-error{color:var(--red)}
`

const stylesTasksBatching = `/* Mobile task batching v33: preserve the full audit while keeping long histories navigable. */
.task-load-more{display:flex;align-items:center;justify-content:center;gap:12px;margin:14px 0 4px;padding:14px;border:1px solid var(--line);border-radius:14px;background:var(--surface);box-shadow:var(--shadow)}.task-load-more span{color:var(--muted);font-size:10px}.task-load-more b{color:var(--ink)}
@media(max-width:820px){.task-load-more{margin-bottom:10px;flex-direction:column}.task-load-more .button{width:100%}}

`
